// Normalize the MQTT payload to a boolean (true = zone open/active).
// Keep msg.topic: the Alarm matches it against each zone 'topic'.
let v = msg.payload;
if (typeof v === "string") {
  const s = v.trim().toLowerCase();
  v = ["on", "true", "1", "open", "opened", "active", "motion", "detected", "yes"].includes(s);
} else if (typeof v === "object" && v !== null && typeof v.value !== "undefined") {
  v = v.value === true || v.value === 1 || v.value === "on";
} else {
  v = v === true || v === 1;
}
msg.payload = v;
return msg;

// Accept a plain string (e.g. "arm", "disarm", "status") or a JSON object.
let p = msg.payload;
if (typeof p === "string") {
  const s = p.trim();
  if (s.startsWith("{")) {
    try { p = JSON.parse(s); } catch (e) { p = { command: s }; }
  } else {
    p = { command: s };
  }
}
if (!p || typeof p !== "object") return null;

const out = { topic: "alarm" }; // must equal the node's controlTopic
if (typeof p.command === "string") out.command = p.command.trim().toLowerCase();
if (typeof p.arm === "string") out.arm = p.arm;
if (typeof p.mode === "string") out.mode = p.mode;
if (p.disarm === true) out.disarm = true;
if (typeof p.code === "string") out.code = p.code;
if (typeof p.zoneTopic === "string") out.zoneTopic = p.zoneTopic;
return out;

// Publish the current alarm mode (retained) so subscribers always see it.
const p = msg.payload && typeof msg.payload === "object" ? msg.payload : {};
const mode = typeof p.mode === "string" ? p.mode : (typeof msg.mode === "string" ? msg.mode : null);
if (!mode) return null;
return { topic: "home/alarm/state", payload: mode, retain: true };
